insert into kafaa_roleplay_scenarios (id, code, kind, title_en, title_ar, summary_en, summary_ar, setting_en, setting_ar, counterpart_en, counterpart_ar, role_en, role_ar, core_skill_ids, skill_ids, level, pass_pct, est_minutes, turns, rubric, sources, status, listed, version, sort, updated_by, updated_at) values
('rp-pb-01', 'RP-PB-01', 'pre_job_brief', 'Pre-job brief for a valve repacking', 'إحاطة ما قبل العمل لإعادة حشو صمام', 'Lead a short pre-job brief: the job, what could go wrong, the critical step and when to stop.', 'قد إحاطة قصيرة قبل العمل: المهمة وما قد يسوء والخطوة الحرجة ومتى نتوقف.', 'You are the work lead for a two-person crew repacking the gland of a manual valve on a non-safety water line (synthetic work package WP-4471). The crew is at the job site; the permit is signed.', 'أنت قائد العمل لطاقم من شخصين يعيد حشو صمام يدوي على خط مياه غير مرتبط بالسلامة (حزمة العمل الافتراضية WP-4471). الطاقم في موقع العمل والتصريح موقّع.', 'A crew member (role card)', 'عضو في الطاقم (بطاقة دور)', 'Work lead', 'قائد العمل', array['cs-peer-check','cs-procedure']::text[], array['sk-fs-tr-dependable','sk-fs-tr-leadership']::text[], 1, 70, 12, '[{"id":"brief","prompt_en":"We are ready when you are. What is the job today, and what could go wrong?","prompt_ar":"نحن جاهزون متى شئت. ما مهمة اليوم، وما الذي قد يسوء؟","hint_en":"Cover the job, the main hazard and what makes us stop.","hint_ar":"غطِّ المهمة والخطر الرئيسي وما يجعلنا نتوقف.","example_en":"Today''s job is to repack the gland on valve V-12 under work package WP-4471. The main hazard is stored energy: the line must be isolated, drained and at zero pressure before anyone loosens a bolt, and the valve body may still be hot. If anything does not match the package, we stop and call the work control desk.","example_ar":"مهمة اليوم هي إعادة حشو الصمام V-12 وفق حزمة العمل WP-4471. الخطر الرئيسي هو الطاقة المخزنة: يجب عزل الخط وتصريفه وأن يكون الضغط صفراً قبل فك أي مسمار، وقد يكون جسم الصمام ساخناً. إذا لم يطابق أي شيء الحزمة نتوقف ونتصل بمكتب التحكم في العمل.","criteria":["scope","hazards","stop"]},{"id":"critical","prompt_en":"Which step do you want us to watch most closely, and how will we check it?","prompt_ar":"أي خطوة تريدنا أن نراقبها عن كثب، وكيف سنتحقق منها؟","hint_en":"Name the step that cannot be undone and the check you agree on.","hint_ar":"سمِّ الخطوة التي لا يمكن التراجع عنها والفحص الذي تتفقون عليه.","example_en":"The critical step is confirming isolation before we open the gland: once it is open there is no going back. We will do a peer check on the isolation points against the permit, and use three-way communication when we confirm zero pressure.","example_ar":"الخطوة الحرجة هي التأكد من العزل قبل فتح الحشوة، فبعد فتحها لا رجوع. سنجري فحص الزميل لنقاط العزل مقابل التصريح، ونستخدم التواصل الثلاثي عند تأكيد انعدام الضغط.","criteria":["critical_step","peer_check"]},{"id":"question","prompt_en":"Quick question: the drawing in the package is revision B but the tag on the valve says revision C. Does that matter?","prompt_ar":"سؤال سريع: المخطط في الحزمة مراجعته B لكن الملصق على الصمام يقول المراجعة C. هل هذا مهم؟","hint_en":"Welcome the question, decide, and check what they saw.","hint_ar":"رحّب بالسؤال واتخذ القرار وتحقق مما رآه.","example_en":"Good catch, thank you for raising it. Yes, it matters: we stop here until work control confirms which revision is correct. Can you show me exactly where the tag and the drawing differ?","example_ar":"ملاحظة جيدة، شكراً لأنك طرحتها. نعم هذا مهم: نتوقف هنا حتى يؤكد مكتب التحكم في العمل المراجعة الصحيحة. هل يمكنك أن تريني أين يختلف الملصق عن المخطط؟","criteria":["acknowledge","stop","check_understanding"]},{"id":"close","prompt_en":"Anything else before we start?","prompt_ar":"هل هناك شيء آخر قبل أن نبدأ؟","hint_en":"Give each person a role and invite last questions.","hint_ar":"حدد دور كل شخص وادعُ إلى الأسئلة الأخيرة.","example_en":"You will do the isolation checks and I will hold the permit and the procedure; the second technician is the peer checker. Is everyone clear on their role, and does anyone have a question before we start?","example_ar":"ستقوم أنت بفحوص العزل وسأمسك أنا التصريح والإجراء، والفني الثاني هو من يجري فحص الزميل. هل الجميع واضح بشأن دوره، وهل لدى أحد سؤال قبل أن نبدأ؟","criteria":["roles","check_understanding"]}]'::jsonb, '[{"id":"scope","label_en":"Names the job","label_ar":"يحدد المهمة","desc_en":"Says what the job is (the task, the valve, the work package).","desc_ar":"يذكر ما هي المهمة (العمل والصمام وحزمة العمل).","tip_en":"Start with one sentence on what we are doing and where.","tip_ar":"ابدأ بجملة واحدة عما نفعله وأين.","check":{"type":"cues","cues":["scope","task","job","work package","valve","repack*","نطاق","المهمة","مهمة","العمل","حزمة العمل","الصمام"]}},{"id":"hazards","label_en":"Names what could go wrong","label_ar":"يحدد ما قد يسوء","desc_en":"Names a hazard or error trap (stored energy, pressure, heat).","desc_ar":"يذكر خطراً أو فخ خطأ (طاقة مخزنة أو ضغط أو حرارة).","tip_en":"Name the one hazard that would hurt someone today.","tip_ar":"سمِّ الخطر الذي قد يؤذي أحداً اليوم.","check":{"type":"cues","cues":["hazard*","risk*","what could go wrong","error-likely","trap*","stored energy","pressur*","hot","خطر*","الخطر*","مخاطر*","المخاطر*","الضغط","ضغط","ساخن*","الطاقة المخزنة"]}},{"id":"stop","label_en":"Says when we stop","label_ar":"يحدد متى نتوقف","desc_en":"States a stop or hold condition (stop, time out, hold point, when in doubt).","desc_ar":"يذكر شرطاً للتوقف أو الانتظار (توقف أو نقطة توقف أو عند الشك).","tip_en":"Tell the crew what makes us stop and who we call.","tip_ar":"أخبر الطاقم بما يجعلنا نتوقف وبمن نتصل.","check":{"type":"cues","cues":["stop*","time out","pause*","hold point","when in doubt","توقف*","نتوقف","نوقف","نقطة توقف","عند الشك"]}},{"id":"critical_step","label_en":"Names the critical step","label_ar":"يحدد الخطوة الحرجة","desc_en":"Identifies the critical or irreversible step (for example confirming isolation).","desc_ar":"يحدد الخطوة الحرجة أو التي لا رجعة فيها (مثل التأكد من العزل).","tip_en":"Say which step cannot be undone and why.","tip_ar":"قل أي خطوة لا يمكن التراجع عنها ولماذا.","check":{"type":"cues","cues":["critical step","critical","irreversible","point of no return","isolation","isolat*","الخطوة الحرجة","خطوة حرجة","حرج*","العزل","عزل"]}},{"id":"peer_check","label_en":"Agrees a verification","label_ar":"يتفق على التحقق","desc_en":"Agrees a peer check, independent verification or three-way communication.","desc_ar":"يتفق على فحص الزميل أو التحقق المستقل أو التواصل الثلاثي.","tip_en":"Agree who checks the critical step and how.","tip_ar":"اتفق على من يتحقق من الخطوة الحرجة وكيف.","check":{"type":"cues","cues":["peer check*","second check","independent verif*","three-way","read back","repeat back","فحص الزميل","التحقق المستقل","التحقق المزدوج","التواصل الثلاثي"]}},{"id":"acknowledge","label_en":"Welcomes the question","label_ar":"يرحب بالسؤال","desc_en":"Thanks the person or acknowledges the catch before answering.","desc_ar":"يشكر الشخص أو يقدّر ملاحظته قبل الإجابة.","tip_en":"Thank people for questions; it keeps them coming.","tip_ar":"اشكر الناس على أسئلتهم؛ فذلك يشجعهم على طرحها.","check":{"type":"cues","cues":["good catch","thank*","glad you","well spotted","right to ask","شكرا","ملاحظة جيدة","أحسنت","سؤال في محله"]}},{"id":"roles","label_en":"Gives each person a role","label_ar":"يحدد دور كل شخص","desc_en":"Says who does what (you will, I will, your role).","desc_ar":"يحدد من يفعل ماذا (ستقوم، سأقوم، دورك).","tip_en":"Close with who does what.","tip_ar":"اختم بتحديد من يفعل ماذا.","check":{"type":"cues","cues":["i will","you will","your role","my role","responsib*","سأقوم","ستقوم","دورك","دوري","مسؤول*"]}},{"id":"check_understanding","label_en":"Checks understanding with a question","label_ar":"يتحقق من الفهم بسؤال","desc_en":"Ends with a real question (a ? or ؟) that invites the other person to respond.","desc_ar":"ينتهي بسؤال حقيقي (؟ أو ?) يدعو الطرف الآخر إلى الرد.","tip_en":"Ask one open question before you move on.","tip_ar":"اطرح سؤالاً مفتوحاً واحداً قبل أن تنتقل.","check":{"type":"question"}}]'::jsonb, '[{"label":"LinkedIn Learning · Role play with AI coach","url":"https://training.talent.linkedin.com/introducing-role-play-with-ai-coach","as_of":"2026-10-10","benchmark_id":"SKILLS-TECH"},{"label":"Udemy · AI-powered role play for business and communication skills (custom scenarios)","url":"https://about.udemy.com/press-releases/udemy-launches-ai-powered-role-play-to-coach-professionals-on-business-and-communication-skills/","as_of":"2026-10-10","benchmark_id":"SKILLS-TECH"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10","benchmark_id":"IAEA-1917"}]'::jsonb, 'published', true, 1, 1, 'p-training-mgr', '2026-09-29T09:00:00Z'),
('rp-st-01', 'RP-ST-01', 'shift_turnover', 'Shift turnover with an open issue', 'تسليم نوبة مع مسألة مفتوحة', 'Hand over an area with a rising trend and an open work order, then confirm the read-back.', 'سلّم منطقة فيها اتجاه متصاعد وأمر عمل مفتوح، ثم أكد قراءة الاستلام.', 'You are finishing a day shift as the area supervisor for building ventilation and chilled water (non-safety). The incoming supervisor has ten minutes for the turnover.', 'تنهي نوبة نهارية بصفتك مشرف منطقة التهوية والمياه المبردة في المباني (غير مرتبطة بالسلامة). لدى المشرف المستلم عشر دقائق للتسليم.', 'The incoming supervisor (role card)', 'المشرف المستلم (بطاقة دور)', 'Outgoing supervisor', 'المشرف المسلِّم', array['cs-comm-stress','cs-peer-check']::text[], array['sk-fs-tr-dependable','sk-fs-tr-empathy']::text[], 1, 70, 10, '[{"id":"status","prompt_en":"I am taking over. What is the status of the area?","prompt_ar":"سأستلم الآن. ما حالة المنطقة؟","hint_en":"Status, open items and times.","hint_ar":"الحالة والبنود المفتوحة والأوقات.","example_en":"Both supply fans are running and the standby chiller is available. One work order is still open on the east air handler, and the filter change is pending until 14:00.","example_ar":"مروحتا الإمداد تعملان والمبرد الاحتياطي متاح. ما زال أمر عمل واحد مفتوحاً على وحدة مناولة الهواء الشرقية، وتغيير المرشح معلق حتى الساعة 14:00.","criteria":["status","open_items","numbers"]},{"id":"abnormal","prompt_en":"Anything abnormal I should know about?","prompt_ar":"هل هناك شيء غير طبيعي ينبغي أن أعرفه؟","hint_en":"What is drifting and what is being done.","hint_ar":"ما الذي ينحرف وما الذي يجري فعله.","example_en":"Yes: the vibration trend on fan B has been rising since Tuesday, still below the alarm limit. I raised a work order and asked the next shift to monitor it every four hours.","example_ar":"نعم، اتجاه الاهتزاز في المروحة ب يرتفع منذ الثلاثاء وما زال دون حد الإنذار. أنشأت أمر عمل وطلبت من النوبة التالية المراقبة كل أربع ساعات.","criteria":["abnormal","action"]},{"id":"first","prompt_en":"What do I need to do first?","prompt_ar":"ما أول ما عليّ فعله؟","hint_en":"One first priority, with a time.","hint_ar":"أولوية أولى واحدة مع وقت.","example_en":"First, check the fan B reading at 10:00 and compare it with the limit. The filter change can wait until after the 14:00 delivery.","example_ar":"أولاً، تحقق من قراءة المروحة ب الساعة 10:00 وقارنها بالحد. ويمكن تأجيل تغيير المرشح إلى ما بعد توريد الساعة 14:00.","criteria":["priority","numbers"]},{"id":"readback","prompt_en":"Let me read back what I have: fans running, one open order, the fan B trend to check at 10:00.","prompt_ar":"دعني أقرأ ما لدي: المراوح تعمل، وأمر مفتوح واحد، واتجاه المروحة ب للتحقق الساعة 10:00.","hint_en":"Confirm or correct, then invite questions.","hint_ar":"أكّد أو صحّح ثم ادعُ إلى الأسئلة.","example_en":"That is correct. One thing to add: the chiller was swapped to standby at 05:00. Do you have any questions before I leave?","example_ar":"صحيح. أضيف أمراً واحداً: نُقل المبرد إلى الاحتياط الساعة 05:00. هل لديك أي أسئلة قبل أن أغادر؟","criteria":["confirm","check_understanding"]}]'::jsonb, '[{"id":"status","label_en":"Gives the status","label_ar":"يقدم الحالة","desc_en":"States equipment status (running, available, in or out of service).","desc_ar":"يذكر حالة المعدات (تعمل، متاحة، في الخدمة أو خارجها).","tip_en":"Lead with what is running and what is not.","tip_ar":"ابدأ بما يعمل وما لا يعمل.","check":{"type":"cues","cues":["status","in service","out of service","running","available","condition","حالة","الحالة","في الخدمة","خارج الخدمة","يعمل","متاح"]}},{"id":"open_items","label_en":"Names open items","label_ar":"يحدد البنود المفتوحة","desc_en":"Mentions what is still open or pending.","desc_ar":"يذكر ما يزال مفتوحاً أو معلقاً.","tip_en":"List what is not finished.","tip_ar":"اذكر ما لم ينتهِ بعد.","check":{"type":"cues","cues":["open","pending","outstanding","in progress","not yet","مفتوح*","معلق*","قيد التنفيذ","لم ينته*"]}},{"id":"numbers","label_en":"Uses numbers and times","label_ar":"يستخدم الأرقام والأوقات","desc_en":"Includes at least one number (a time, a value or a count).","desc_ar":"يتضمن رقماً واحداً على الأقل (وقتاً أو قيمة أو عدداً).","tip_en":"Give the time or value, not \"soon\" or \"high\".","tip_ar":"اذكر الوقت أو القيمة لا \"قريباً\" أو \"مرتفع\".","check":{"type":"digit"}},{"id":"abnormal","label_en":"Flags what is abnormal","label_ar":"ينبه إلى غير الطبيعي","desc_en":"Names an abnormal or degraded condition, a trend or an alarm.","desc_ar":"يذكر حالة غير طبيعية أو متدهورة أو اتجاهاً أو إنذاراً.","tip_en":"Say what is drifting, even if it is still within limits.","tip_ar":"قل ما ينحرف حتى لو كان ضمن الحدود.","check":{"type":"cues","cues":["abnormal","degraded","trend*","alarm*","limit*","higher than","lower than","غير طبيعي*","متدهور*","اتجاه*","إنذار*","الحد","حد"]}},{"id":"action","label_en":"Says what is being done","label_ar":"يذكر ما يجري فعله","desc_en":"Says what action is in place (a work order, monitoring, a next step).","desc_ar":"يذكر الإجراء القائم (أمر عمل أو مراقبة أو خطوة تالية).","tip_en":"Pair every issue with its action and owner.","tip_ar":"اربط كل مسألة بإجرائها ومسؤولها.","check":{"type":"cues","cues":["action","work order","raised","next step","monitor*","i have","we have","إجراء","الإجراء","أمر عمل","راقب*","المراقبة","نراقب"]}},{"id":"priority","label_en":"Sets the first priority","label_ar":"يحدد الأولوية الأولى","desc_en":"Says what to do first or before something else.","desc_ar":"يحدد ما يُفعل أولاً أو قبل غيره.","tip_en":"Tell them the one thing to do first.","tip_ar":"أخبره بالشيء الوحيد الذي يُفعل أولاً.","check":{"type":"cues","cues":["first","priority","before","urgent","أولا","أولوية","الأولوية","قبل","عاجل"]}},{"id":"confirm","label_en":"Confirms the read-back","label_ar":"يؤكد قراءة الاستلام","desc_en":"Confirms or corrects the incoming supervisor''s read-back.","desc_ar":"يؤكد قراءة المشرف المستلم أو يصححها.","tip_en":"Say \"correct\" or correct it; never let a wrong read-back pass.","tip_ar":"قل \"صحيح\" أو صحّحها؛ ولا تترك قراءة خاطئة تمر.","check":{"type":"cues","cues":["correct","that is right","confirm*","agreed","yes","صحيح","أؤكد","نعم","موافق"]}},{"id":"check_understanding","label_en":"Checks understanding with a question","label_ar":"يتحقق من الفهم بسؤال","desc_en":"Ends with a real question (a ? or ؟) that invites the other person to respond.","desc_ar":"ينتهي بسؤال حقيقي (؟ أو ?) يدعو الطرف الآخر إلى الرد.","tip_en":"Ask one open question before you move on.","tip_ar":"اطرح سؤالاً مفتوحاً واحداً قبل أن تنتقل.","check":{"type":"question"}}]'::jsonb, '[{"label":"LinkedIn Learning · Role play with AI coach","url":"https://training.talent.linkedin.com/introducing-role-play-with-ai-coach","as_of":"2026-10-10","benchmark_id":"SKILLS-TECH"},{"label":"Udemy · AI-powered role play for business and communication skills (custom scenarios)","url":"https://about.udemy.com/press-releases/udemy-launches-ai-powered-role-play-to-coach-professionals-on-business-and-communication-skills/","as_of":"2026-10-10","benchmark_id":"SKILLS-TECH"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10","benchmark_id":"IAEA-1917"}]'::jsonb, 'published', true, 1, 2, 'p-training-mgr', '2026-09-29T09:00:00Z'),
('rp-rc-01', 'RP-RC-01', 'raise_concern', 'Raising a concern to a busy senior', 'رفع ملاحظة إلى مسؤول أعلى مشغول', 'Practise raising a technical concern clearly and respectfully when the senior pushes back. For a real concern, use the speak-up channels.', 'تدرّب على رفع ملاحظة فنية بوضوح واحترام عندما يعترض المسؤول الأعلى. للمخاوف الحقيقية استخدم قنوات الإبلاغ.', 'You noticed that the tag of a temporary modification on a non-safety cooling line shows a removal date that has passed. The section head is between meetings. The situation is fictional practice material.', 'لاحظت أن ملصق تعديل مؤقت على خط تبريد غير مرتبط بالسلامة يُظهر تاريخ إزالة قد انقضى. رئيس القسم بين اجتماعين. الموقف مادة تدريبية افتراضية.', 'A section head (role card)', 'رئيس قسم (بطاقة دور)', 'Technician', 'فني', array['cs-speak-up','cs-questioning']::text[], array['sk-fs-tr-leadership','sk-fs-tr-analytical']::text[], 2, 70, 12, '[{"id":"open","prompt_en":"I have only got two minutes. What is it?","prompt_ar":"لدي دقيقتان فقط. ما الأمر؟","hint_en":"Say the concern and the facts in two sentences.","hint_ar":"اذكر الملاحظة والحقائق في جملتين.","example_en":"I have a concern about the temporary modification on the cooling line. I checked the tag this morning: its removal date was 14 September, so it has expired.","example_ar":"لدي قلق بشأن التعديل المؤقت على خط التبريد. تحققت من الملصق هذا الصباح: تاريخ إزالته كان 14 سبتمبر، أي أنه منتهٍ.","criteria":["concern","facts"]},{"id":"push","prompt_en":"It has been like that for weeks. It is fine.","prompt_ar":"إنه كذلك منذ أسابيع. لا بأس.","hint_en":"Acknowledge, then hold the point with the safety reason.","hint_ar":"أقرّ ثم تمسك بالفكرة مع سبب السلامة.","example_en":"I understand it looks fine, but an expired temporary modification means the configuration is no longer what the procedure assumes, and that is a safety margin question.","example_ar":"أتفهم أنه يبدو سليماً، لكن انتهاء التعديل المؤقت يعني أن التهيئة لم تعد كما يفترضها الإجراء، وهذه مسألة تتعلق بهامش السلامة.","criteria":["persist","safety_reason"]},{"id":"ask","prompt_en":"So what do you want me to do about it?","prompt_ar":"إذن ماذا تريدني أن أفعل حيال ذلك؟","hint_en":"One specific action and a time.","hint_ar":"إجراء محدد واحد ووقت.","example_en":"Could you ask engineering to confirm today whether it can stay, and if not, plan its removal before the end of this shift?","example_ar":"هل يمكن أن تطلب من الهندسة التأكد اليوم إن كان يمكن إبقاؤه، وإن لم يكن، التخطيط لإزالته قبل نهاية هذه النوبة؟","criteria":["specific_ask","timing"]},{"id":"refuse","prompt_en":"And if I say no?","prompt_ar":"وإن قلت لا؟","hint_en":"The formal route, said respectfully.","hint_ar":"المسار الرسمي، بأسلوب محترم.","example_en":"Then I would respect that it is your call, but I would raise a condition report so the question gets a documented answer. Thank you for hearing me out.","example_ar":"عندها أحترم أن القرار لك، لكنني سأرفع تقرير حالة حتى يحصل السؤال على إجابة موثقة. شكراً لأنك استمعت إلي.","criteria":["escalate","respect"]}]'::jsonb, '[{"id":"concern","label_en":"States the concern plainly","label_ar":"يذكر الملاحظة بوضوح","desc_en":"Says there is a concern or problem in the first sentence.","desc_ar":"يذكر في الجملة الأولى أن هناك ملاحظة أو مشكلة.","tip_en":"Lead with \"I have a concern about ...\"","tip_ar":"ابدأ بـ \"لدي قلق بشأن ...\"","check":{"type":"cues","cues":["concern*","worried","not right","issue","problem","قلق*","مخاوف","مشكلة","غير صحيح"]}},{"id":"facts","label_en":"Gives the facts","label_ar":"يقدم الحقائق","desc_en":"Says what was seen or checked (the tag, the date).","desc_ar":"يذكر ما رآه أو تحقق منه (الملصق والتاريخ).","tip_en":"Say what you saw, where and when.","tip_ar":"قل ما رأيته وأين ومتى.","check":{"type":"cues","cues":["i saw","i checked","i noticed","observed","tag","date","expired","رأيت","لاحظت","تحققت","الملصق","تاريخ"]}},{"id":"persist","label_en":"Holds the point respectfully","label_ar":"يتمسك بالفكرة باحترام","desc_en":"Acknowledges the push-back and still holds the point (but, however, even so).","desc_ar":"يقر بالاعتراض ويتمسك بالفكرة (لكن، ومع ذلك).","tip_en":"Acknowledge, then say \"but\" and the reason.","tip_ar":"أقرّ ثم قل \"لكن\" واذكر السبب.","check":{"type":"cues","cues":["even so","i understand but","however","respectfully","still think","but","مع ذلك","ومع ذلك","لكن","أتفهم"]}},{"id":"safety_reason","label_en":"Gives the safety reason","label_ar":"يذكر سبب السلامة","desc_en":"Links the concern to safety, risk, configuration or the procedure.","desc_ar":"يربط الملاحظة بالسلامة أو المخاطر أو التهيئة أو الإجراء.","tip_en":"Say why it matters for safety, not only for the rules.","tip_ar":"قل لماذا يهم ذلك للسلامة لا للقواعد فقط.","check":{"type":"cues","cues":["safety","risk","configuration","margin","procedure","السلامة","سلامة","المخاطر","خطر","الإجراء","التهيئة"]}},{"id":"specific_ask","label_en":"Makes a specific ask","label_ar":"يقدم طلباً محدداً","desc_en":"Asks for a specific action (could you, I suggest, please).","desc_ar":"يطلب إجراءً محدداً (هل يمكن، أقترح، أرجو).","tip_en":"Ask for one concrete action.","tip_ar":"اطلب إجراءً واحداً ملموساً.","check":{"type":"cues","cues":["could you","can we","i suggest","i propose","please","would you","أقترح","هل يمكن","أرجو","هل نستطيع"]}},{"id":"timing","label_en":"Gives a time","label_ar":"يحدد وقتاً","desc_en":"Says by when (today, before the end of the shift, now).","desc_ar":"يحدد متى (اليوم، قبل نهاية النوبة، الآن).","tip_en":"Put a time on your ask.","tip_ar":"ضع وقتاً لطلبك.","check":{"type":"cues","cues":["today","before","by the end","now","this shift","اليوم","قبل","الآن","هذه النوبة"]}},{"id":"escalate","label_en":"Names the next step if refused","label_ar":"يحدد الخطوة التالية عند الرفض","desc_en":"Names the formal route if the answer is no (a condition report, the shift manager).","desc_ar":"يذكر المسار الرسمي إذا كان الجواب لا (تقرير حالة أو مدير النوبة).","tip_en":"Know your next step before you need it.","tip_ar":"اعرف خطوتك التالية قبل أن تحتاج إليها.","check":{"type":"cues","cues":["escalat*","condition report","corrective action","next level","shift manager","تصعيد","أصعد","تقرير حالة","مدير النوبة","الإجراء التصحيحي"]}},{"id":"respect","label_en":"Stays respectful","label_ar":"يحافظ على الاحترام","desc_en":"Thanks the person or shows respect for their role.","desc_ar":"يشكر الشخص أو يُظهر احترامه لدوره.","tip_en":"Thank them for their time, whatever the answer.","tip_ar":"اشكره على وقته أياً كان الجواب.","check":{"type":"cues","cues":["respect*","thank*","appreciate","شكرا","أقدر","احترام","أحترم"]}}]'::jsonb, '[{"label":"LinkedIn Learning · Role play with AI coach","url":"https://training.talent.linkedin.com/introducing-role-play-with-ai-coach","as_of":"2026-10-10","benchmark_id":"SKILLS-TECH"},{"label":"Udemy · AI-powered role play for business and communication skills (custom scenarios)","url":"https://about.udemy.com/press-releases/udemy-launches-ai-powered-role-play-to-coach-professionals-on-business-and-communication-skills/","as_of":"2026-10-10","benchmark_id":"SKILLS-TECH"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10","benchmark_id":"IAEA-1917"}]'::jsonb, 'published', true, 1, 3, 'p-training-mgr', '2026-09-29T09:00:00Z'),
('rp-ri-01', 'RP-RI-01', 'regulator_interview', 'Inspection-style interview practice', 'تمرين على مقابلة بأسلوب التفتيش', 'Answer inspection-style questions about procedure use honestly and concretely. Practice only: Kafa''a is not a regulator and this is not an inspection.', 'أجب عن أسئلة بأسلوب التفتيش حول استخدام الإجراءات بصدق ووضوح. تمرين فقط: كفاءة ليست جهة رقابية وهذا ليس تفتيشاً.', 'A colleague plays an inspector asking how you work with procedures in your own area. Answer as you would in a real interview: concrete, first-hand and honest about what you do not know.', 'يؤدي زميل دور مفتش يسألك كيف تعمل بالإجراءات في منطقتك. أجب كما تفعل في مقابلة حقيقية: بوضوح ومن واقع تجربتك وبصدق بشأن ما لا تعرفه.', 'A practice interviewer playing an inspector (role card)', 'محاور تدريبي يؤدي دور مفتش (بطاقة دور)', 'Interviewee', 'الشخص الذي تجري مقابلته', array['cs-procedure','cs-accountability']::text[], array['sk-fs-tr-analytical','sk-fs-tr-selfaware']::text[], 2, 70, 15, '[{"id":"revision","prompt_en":"Walk me through how you know you are using the current revision of a procedure.","prompt_ar":"اشرح لي كيف تعرف أنك تستخدم المراجعة السارية من الإجراء.","hint_en":"Describe your own check, concretely.","hint_ar":"صف فحصك أنت بشكل ملموس.","example_en":"Before I start any task I check the revision number on my copy against the document control system, and I only work from a controlled copy printed that day. If the numbers differ, I get the current revision before I begin.","example_ar":"قبل أن أبدأ أي مهمة أتحقق من رقم المراجعة في نسختي مقارنة بنظام ضبط الوثائق، ولا أعمل إلا من النسخة المعتمدة المطبوعة في اليوم نفسه. وإذا اختلف الرقمان أحصل على المراجعة السارية قبل أن أبدأ.","criteria":["concrete","length"]},{"id":"cannot","prompt_en":"What do you do if the procedure cannot be followed as written?","prompt_ar":"ماذا تفعل إذا تعذر اتباع الإجراء كما هو مكتوب؟","hint_en":"Stop, tell the right person, no workaround.","hint_ar":"توقف وأبلغ الشخص المناسب ولا التفاف.","example_en":"I stop at a safe point and tell my supervisor, who contacts the procedure owner. I would never work around a step or improvise, even under time pressure.","example_ar":"أتوقف عند نقطة آمنة وأبلغ المشرف الذي يتواصل مع مالك الإجراء. لن أتجاوز أي خطوة أو أرتجل أبداً، حتى تحت ضغط الوقت.","criteria":["stop","escalate","no_workaround"]},{"id":"example","prompt_en":"Give me an example from your own work.","prompt_ar":"أعطني مثالاً من عملك.","hint_en":"When it happened, what you did, what came of it.","hint_ar":"متى حدث وماذا فعلت وما الذي نتج.","example_en":"Last year, during a calibration, I found a step that referred to a tool we no longer use. I stopped and raised it; as a result the procedure was corrected within a week.","example_ar":"خلال معايرة في العام الماضي وجدت خطوة تشير إلى أداة لم نعد نستخدمها. توقفت وأبلغت عنها، وكانت النتيجة تصحيح الإجراء خلال أسبوع.","criteria":["example","result"]},{"id":"unknown","prompt_en":"Is there anything you do not know the answer to?","prompt_ar":"هل هناك شيء لا تعرف إجابته؟","hint_en":"Be honest and say how you will find out.","hint_ar":"كن صادقاً وقل كيف ستعرف.","example_en":"I am not sure how often the document control system is audited, so I would not guess. I will find out from the procedure owner and come back to you today.","example_ar":"لست متأكداً من عدد مرات تدقيق نظام ضبط الوثائق، لذلك لن أخمّن. سأتحقق من مالك الإجراء وأعود إليك اليوم.","criteria":["honest","length"]}]'::jsonb, '[{"id":"concrete","label_en":"Describes what you actually do","label_ar":"يصف ما تفعله فعلاً","desc_en":"Describes a concrete check (the revision, document control, a controlled copy).","desc_ar":"يصف فحصاً ملموساً (المراجعة، ضبط الوثائق، النسخة المعتمدة).","tip_en":"Say what you do, step by step, not what people should do.","tip_ar":"قل ما تفعله خطوة بخطوة لا ما ينبغي أن يفعله الناس.","check":{"type":"cues","cues":["i check","i verify","revision","document control","controlled copy","current","أتحقق","المراجعة","النسخة المعتمدة","ضبط الوثائق","السارية"]}},{"id":"length","label_en":"Answers in enough depth","label_ar":"يجيب بعمق كافٍ","desc_en":"Between 15 and 180 words: enough to be specific, short enough to stay clear.","desc_ar":"بين 15 و180 كلمة: ما يكفي للتحديد ويبقى واضحاً.","tip_en":"Two or three sentences usually work best.","tip_ar":"جملتان أو ثلاث تكفي عادة.","check":{"type":"length","min":15,"max":180}},{"id":"stop","label_en":"Stops when it cannot be followed","label_ar":"يتوقف عند تعذر الاتباع","desc_en":"Says they stop or pause at a safe point.","desc_ar":"يذكر أنه يتوقف عند نقطة آمنة.","tip_en":"Say that you stop first.","tip_ar":"قل إنك تتوقف أولاً.","check":{"type":"cues","cues":["stop*","pause*","hold","أتوقف","توقف*","نتوقف"]}},{"id":"escalate","label_en":"Involves the right person","label_ar":"يُشرك الشخص المناسب","desc_en":"Names who they tell (the supervisor, the procedure owner, a change request).","desc_ar":"يذكر من يُبلغ (المشرف أو مالك الإجراء أو طلب تغيير).","tip_en":"Name the person or route, not just \"someone\".","tip_ar":"سمِّ الشخص أو المسار لا \"أحداً ما\".","check":{"type":"cues","cues":["supervisor","shift manager","procedure owner","raise","change request","المشرف","مالك الإجراء","أبلغ","طلب تغيير"]}},{"id":"no_workaround","label_en":"Rules out workarounds","label_ar":"يستبعد الالتفاف","desc_en":"Says they would not work around or improvise.","desc_ar":"يذكر أنه لن يلتف على الإجراء أو يرتجل.","tip_en":"Say clearly what you would never do.","tip_ar":"قل بوضوح ما لن تفعله أبداً.","check":{"type":"cues","cues":["never","do not","would not","wouldn t","لن","أبدا","لا أعمل"]}},{"id":"example","label_en":"Gives a real example","label_ar":"يقدم مثالاً حقيقياً","desc_en":"Sets the scene of an example (when, during, last year).","desc_ar":"يحدد سياق مثال (عندما، خلال، العام الماضي).","tip_en":"Start with when and where it happened.","tip_ar":"ابدأ بمتى وأين حدث ذلك.","check":{"type":"cues","cues":["when","during","last year","once","last month","عندما","خلال","العام الماضي","مرة"]}},{"id":"result","label_en":"Says what came of it","label_ar":"يذكر ما نتج عنه","desc_en":"Says the result or what was learned.","desc_ar":"يذكر النتيجة أو ما تعلمه.","tip_en":"End the example with its outcome.","tip_ar":"اختم المثال بنتيجته.","check":{"type":"cues","cues":["result","outcome","learned","learnt","as a result","النتيجة","نتيجة","تعلمت"]}},{"id":"honest","label_en":"Is honest about limits","label_ar":"يتحلى بالصدق بشأن حدود معرفته","desc_en":"Admits not knowing and says how they will find out.","desc_ar":"يعترف بعدم المعرفة ويذكر كيف سيعرف.","tip_en":"Never guess: say you will find out.","tip_ar":"لا تخمّن أبداً: قل إنك ستتحقق.","check":{"type":"cues","cues":["i do not know","i don t know","not sure","find out","come back","follow up","لا أعرف","لست متأكد*","سأتحقق","سأعود"]}}]'::jsonb, '[{"label":"LinkedIn Learning · Role play with AI coach","url":"https://training.talent.linkedin.com/introducing-role-play-with-ai-coach","as_of":"2026-10-10","benchmark_id":"SKILLS-TECH"},{"label":"Udemy · AI-powered role play for business and communication skills (custom scenarios)","url":"https://about.udemy.com/press-releases/udemy-launches-ai-powered-role-play-to-coach-professionals-on-business-and-communication-skills/","as_of":"2026-10-10","benchmark_id":"SKILLS-TECH"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10","benchmark_id":"IAEA-1917"}]'::jsonb, 'published', true, 1, 4, 'p-training-mgr', '2026-09-29T09:00:00Z'),
('rp-kt-01', 'RP-KT-01', 'knowledge_transfer', 'Knowledge-transfer session with a vendor expert', 'جلسة نقل معرفة مع خبير من المورد', 'Lead a session with a visiting expert in English, check your understanding and capture the know-how for your team in Arabic.', 'قد جلسة مع خبير زائر باللغة الإنجليزية، وتحقق من فهمك، ووثّق المعرفة لفريقك بالعربية.', 'An expert from a partner vendor (synthetic) explains how their team inspects pump seals. You lead the session and will train your own team afterwards.', 'يشرح خبير من مورد شريك (افتراضي) كيف يفحص فريقه موانع التسرب في المضخات. تقود الجلسة وستدرّب فريقك بعدها.', 'A visiting vendor expert (role card)', 'خبير زائر من المورد (بطاقة دور)', 'Session lead', 'قائد الجلسة', array['cs-cross-cultural','cs-developing']::text[], array['sk-fs-tr-crosscultural','sk-fs-tr-empathy']::text[], 1, 60, 15, '[{"id":"open","prompt_en":"Shall I just start explaining how we inspect the pump seals?","prompt_ar":"هل أبدأ مباشرة في شرح طريقة فحصنا لموانع التسرب؟","hint_en":"Set the goal and say what you need.","hint_ar":"حدد الهدف وقل ما تحتاجه.","example_en":"Thank you for coming. Before you start, our goal today is to understand your seal inspection method well enough to train our own team. We need most detail on the acceptance limits and the common mistakes.","example_ar":"شكراً لحضورك. قبل أن تبدأ، الهدف اليوم أن نفهم طريقتك في فحص موانع التسرب بما يكفي لتدريب فريقنا. نحتاج إلى أكبر قدر من التفاصيل عن حدود القبول والأخطاء الشائعة.","criteria":["goal","needs"]},{"id":"check","prompt_en":"So the wear groove is measured at four points, and anything over the limit is rejected. Clear so far?","prompt_ar":"إذن يُقاس أخدود التآكل عند أربع نقاط، ويُرفض كل ما يتجاوز الحد. هل الأمر واضح حتى الآن؟","hint_en":"Paraphrase and check with a question.","hint_ar":"أعد الصياغة وتحقق بسؤال.","example_en":"Yes. If I understand correctly, you measure at four points around the face and reject the seal if any single point is over the limit, not the average. Is that right?","example_ar":"نعم. إذا فهمت جيداً، تقيسون عند أربع نقاط حول الوجه وترفضون مانع التسرب إذا تجاوزت أي نقطة واحدة الحد، وليس المتوسط. هل هذا صحيح؟","criteria":["paraphrase","check_understanding"]},{"id":"context","prompt_en":"That is how we do it at our plant.","prompt_ar":"هكذا نفعل ذلك في محطتنا.","hint_en":"Relate it to your own procedure and capture it.","hint_ar":"اربطه بإجراءاتك ووثّقه.","example_en":"That is useful. Our procedure here uses a different gauge, so I will note where the steps differ and we will record your method as a knowledge asset for review.","example_ar":"هذا مفيد. يستخدم الإجراء لدينا مقياساً مختلفاً، لذلك سأدوّن مواضع الاختلاف. سنوثق طريقتك أصلاً معرفياً للمراجعة.","criteria":["context","capture"]},{"id":"close","prompt_en":"Anything else?","prompt_ar":"هل هناك شيء آخر؟","hint_en":"Summarise and agree the follow-up.","hint_ar":"لخّص واتفق على المتابعة.","example_en":"Let me summarise the key points: four measuring points, reject on any single point, and record the gauge used. I will send the notes to you for checking before our next session.","example_ar":"دعني أذكر النقاط الرئيسية: أربع نقاط قياس، والرفض عند أي نقطة واحدة، وتسجيل المقياس المستخدم. سأرسل الملاحظات إليك للتحقق قبل الجلسة القادمة.","criteria":["summary","next"]}]'::jsonb, '[{"id":"goal","label_en":"Sets the goal","label_ar":"يحدد الهدف","desc_en":"States the goal or agenda of the session.","desc_ar":"يذكر هدف الجلسة أو جدولها.","tip_en":"Open with what you want to be able to do afterwards.","tip_ar":"ابدأ بما تريد أن تستطيع فعله بعد الجلسة.","check":{"type":"cues","cues":["goal","objective","agenda","today we","purpose","aim","الهدف","جدول","هدفنا","الغرض"]}},{"id":"needs","label_en":"Says what you need most","label_ar":"يذكر ما تحتاجه أكثر","desc_en":"Says what the team needs most from the expert.","desc_ar":"يذكر ما يحتاجه الفريق أكثر من الخبير.","tip_en":"Point the expert at the part that matters to you.","tip_ar":"وجّه الخبير إلى الجزء الذي يهمك.","check":{"type":"cues","cues":["we need","we want","i would like","focus on","most useful","نحتاج","نريد","أود","نركز"]}},{"id":"paraphrase","label_en":"Checks by paraphrasing","label_ar":"يتحقق بإعادة الصياغة","desc_en":"Restates the point in their own words (if I understand, in other words).","desc_ar":"يعيد صياغة الفكرة بكلماته (إذا فهمت، بمعنى).","tip_en":"Say it back in your words.","tip_ar":"أعد قولها بكلماتك.","check":{"type":"cues","cues":["so you mean","if i understand","in other words","to check","so what you are saying","let me repeat","إذا فهمت","بمعنى","أي أن","دعني أعيد"]}},{"id":"check_understanding","label_en":"Checks understanding with a question","label_ar":"يتحقق من الفهم بسؤال","desc_en":"Ends with a real question (a ? or ؟) that invites the other person to respond.","desc_ar":"ينتهي بسؤال حقيقي (؟ أو ?) يدعو الطرف الآخر إلى الرد.","tip_en":"Ask one open question before you move on.","tip_ar":"اطرح سؤالاً مفتوحاً واحداً قبل أن تنتقل.","check":{"type":"question"}},{"id":"context","label_en":"Relates it to your context","label_ar":"يربطها بسياقك","desc_en":"Notes how your own plant or procedure differs.","desc_ar":"يلاحظ كيف تختلف محطتك أو إجراءاتك.","tip_en":"Ask yourself what is different here.","tip_ar":"اسأل نفسك ما المختلف هنا.","check":{"type":"cues","cues":["our plant","here","our procedure","differ*","locally","في محطتنا","لدينا","هنا","يختلف","تختلف"]}},{"id":"capture","label_en":"Captures the knowledge","label_ar":"يوثق المعرفة","desc_en":"Says how the knowledge will be written down or recorded.","desc_ar":"يذكر كيف ستُدوّن المعرفة أو تُسجل.","tip_en":"Agree how it will be captured before the expert leaves.","tip_ar":"اتفق على طريقة التوثيق قبل مغادرة الخبير.","check":{"type":"cues","cues":["write","record*","capture","document*","knowledge asset","note*","نوثق","أسجل","توثيق","سنوثق","نسجل"]}},{"id":"summary","label_en":"Summarises the key points","label_ar":"يلخص النقاط الرئيسية","desc_en":"Summarises the key points at the end.","desc_ar":"يلخص النقاط الرئيسية في النهاية.","tip_en":"Close with three key points.","tip_ar":"اختم بثلاث نقاط رئيسية.","check":{"type":"cues","cues":["summary","to summarise","key points","three points","in short","الخلاصة","النقاط الرئيسية","باختصار"]}},{"id":"next","label_en":"Agrees the follow-up","label_ar":"يتفق على المتابعة","desc_en":"Agrees what happens next (send notes, a next session).","desc_ar":"يتفق على ما يحدث بعد ذلك (إرسال الملاحظات أو جلسة قادمة).","tip_en":"End with who sends what, and when.","tip_ar":"اختم بمن يرسل ماذا ومتى.","check":{"type":"cues","cues":["next session","follow-up","follow up","send","share","الجلسة القادمة","متابعة","سأرسل","نشارك"]}}]'::jsonb, '[{"label":"LinkedIn Learning · Role play with AI coach","url":"https://training.talent.linkedin.com/introducing-role-play-with-ai-coach","as_of":"2026-10-10","benchmark_id":"SKILLS-TECH"},{"label":"Udemy · AI-powered role play for business and communication skills (custom scenarios)","url":"https://about.udemy.com/press-releases/udemy-launches-ai-powered-role-play-to-coach-professionals-on-business-and-communication-skills/","as_of":"2026-10-10","benchmark_id":"SKILLS-TECH"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10","benchmark_id":"IAEA-1917"}]'::jsonb, 'published', true, 1, 5, 'p-training-mgr', '2026-09-29T09:00:00Z'),
('rp-ai-01', 'RP-AI-01', 'ai_peer_coaching', 'Coaching a peer on an AI output', 'توجيه زميل بشأن مخرجات ذكاء اصطناعي', 'A colleague pasted an AI-drafted summary into a report without checking it. Coach them to verify and disclose, without blame.', 'ألصق زميل ملخصاً صاغه الذكاء الاصطناعي في تقرير دون التحقق منه. وجّهه إلى التحقق والإفصاح دون لوم.', 'Your colleague used an approved AI assistant to summarise a year of work orders for a pump and pasted the summary into a quarterly report. You noticed one date that looks wrong.', 'استخدم زميلك مساعد ذكاء اصطناعي معتمداً لتلخيص أوامر العمل لمضخة على مدى عام، وألصق الملخص في تقرير ربع سنوي. لاحظت تاريخاً يبدو خاطئاً.', 'A colleague (role card)', 'زميل (بطاقة دور)', 'Peer coach', 'زميل موجِّه', array['cs-digital-judgement','cs-developing']::text[], array['sk-fs-ai-verify','sk-fs-tr-empathy']::text[], 2, 70, 12, '[{"id":"open","prompt_en":"The AI tool wrote the summary of the work-order history. It is probably right, is it not?","prompt_ar":"كتبت أداة الذكاء الاصطناعي ملخص سجل أوامر العمل. هو صحيح على الأرجح، أليس كذلك؟","hint_en":"Acknowledge the effort, then ask for verification.","hint_ar":"قدّر الجهد ثم اطلب التحقق.","example_en":"I understand, it reads well and it is a good start. But a summary like this has to be checked against the original work orders before it goes into a report.","example_ar":"أتفهم ذلك، فهو مكتوب بشكل جيد وبداية جيدة. لكن ملخصاً كهذا يجب أن نتحقق منه مقابل أوامر العمل الأصلية قبل أن يدخل في تقرير.","criteria":["tone","verify"]},{"id":"what","prompt_en":"What exactly should I check?","prompt_ar":"ما الذي يجب أن أتحقق منه بالضبط؟","hint_en":"The details and a method.","hint_ar":"التفاصيل والطريقة.","example_en":"Start with the dates, the tag numbers and the references to procedures: compare each one against the work-order records, side by side.","example_ar":"تحقق أولاً من التواريخ والأرقام ومراجع الإجراءات، ثم قارن كل واحد منها مقابل سجلات أوامر العمل.","criteria":["specifics","method"]},{"id":"disclose","prompt_en":"Do I have to tell anyone that AI drafted it?","prompt_ar":"هل عليّ أن أخبر أحداً بأن الذكاء الاصطناعي صاغه؟","hint_en":"Disclosure, and the guidance behind it.","hint_ar":"الإفصاح والإرشادات التي تستند إليه.","example_en":"Yes. The guidance for approved AI tools says we state when a draft came from AI, so mention it in the report and say that you verified it.","example_ar":"نعم. تنص الإرشادات الخاصة بأدوات الذكاء الاصطناعي المعتمدة على أن نذكر متى جاءت المسودة من الذكاء الاصطناعي، فاذكر ذلك في التقرير ووضّح أنك تحققت منها.","criteria":["transparency","policy"]},{"id":"next","prompt_en":"OK. What would you do next time?","prompt_ar":"حسناً. ماذا ستفعل في المرة القادمة؟","hint_en":"One habit, then check they agree.","hint_ar":"عادة واحدة ثم تأكد من موافقته.","example_en":"Next time, make the comparison a habit: draft with the tool, then check every number before you share it. Does that work for you?","example_ar":"في المرة القادمة اجعل المقارنة عادة: اكتب المسودة بالأداة ثم تحقق من كل رقم قبل مشاركتها. هل يناسبك ذلك؟","criteria":["plan","check_understanding"]}]'::jsonb, '[{"id":"tone","label_en":"Opens without blame","label_ar":"يبدأ دون لوم","desc_en":"Acknowledges the effort first (I understand, a good start).","desc_ar":"يقدّر الجهد أولاً (أتفهم، بداية جيدة).","tip_en":"Start with what was useful.","tip_ar":"ابدأ بما كان مفيداً.","check":{"type":"cues","cues":["i understand","good start","i see why","fair","useful","أتفهم","بداية جيدة","مفيد"]}},{"id":"verify","label_en":"Asks for verification","label_ar":"يطلب التحقق","desc_en":"Says the output must be checked against the source or original records.","desc_ar":"يذكر أنه يجب التحقق من المخرجات مقابل المصدر أو السجلات الأصلية.","tip_en":"Name the source to check against.","tip_ar":"سمِّ المصدر الذي يُتحقق منه.","check":{"type":"cues","cues":["verif*","check*","source*","original","controlled","تحقق","نتحقق","المصدر","الأصلية","السجلات"]}},{"id":"specifics","label_en":"Names what to check","label_ar":"يحدد ما يُتحقق منه","desc_en":"Names the details to check (dates, numbers, tag numbers, references).","desc_ar":"يحدد التفاصيل التي يُتحقق منها (التواريخ والأرقام والمراجع).","tip_en":"Point at the details AI gets wrong most.","tip_ar":"أشر إلى التفاصيل التي يخطئ فيها الذكاء الاصطناعي أكثر.","check":{"type":"cues","cues":["dates","numbers","names","tag numbers","references","figures","التواريخ","الأرقام","المراجع"]}},{"id":"method","label_en":"Gives a method","label_ar":"يقدم طريقة","desc_en":"Says how to check (compare, against, side by side, line by line).","desc_ar":"يذكر طريقة التحقق (قارن، مقابل، سطراً بسطر).","tip_en":"Give a simple method they can repeat.","tip_ar":"قدّم طريقة بسيطة يمكن تكرارها.","check":{"type":"cues","cues":["compare","against","side by side","cross-check","line by line","قارن","نقارن","مقابل","سطرا بسطر"]}},{"id":"transparency","label_en":"Asks for disclosure","label_ar":"يطلب الإفصاح","desc_en":"Says the use of AI should be stated or mentioned.","desc_ar":"يذكر أنه ينبغي ذكر استخدام الذكاء الاصطناعي أو توضيحه.","tip_en":"Say the report should say an AI tool drafted it.","tip_ar":"قل إن التقرير يجب أن يذكر أن أداة ذكاء اصطناعي صاغته.","check":{"type":"cues","cues":["disclose","mention","label","say that","state","الإفصاح","نذكر","اذكر","توضيح"]}},{"id":"policy","label_en":"Points to the guidance","label_ar":"يشير إلى الإرشادات","desc_en":"Refers to the approved-tool guidance or policy.","desc_ar":"يشير إلى إرشادات الأدوات المعتمدة أو السياسة.","tip_en":"Point to the guidance, not your opinion.","tip_ar":"أشر إلى الإرشادات لا إلى رأيك.","check":{"type":"cues","cues":["approved","policy","guidance","rule","المعتمدة","السياسة","الإرشادات"]}},{"id":"plan","label_en":"Agrees a habit for next time","label_ar":"يتفق على عادة للمرة القادمة","desc_en":"Agrees what to do next time.","desc_ar":"يتفق على ما يُفعل في المرة القادمة.","tip_en":"End with one habit for next time.","tip_ar":"اختم بعادة واحدة للمرة القادمة.","check":{"type":"cues","cues":["next time","from now on","in future","habit","المرة القادمة","مستقبلا","من الآن"]}},{"id":"check_understanding","label_en":"Checks understanding with a question","label_ar":"يتحقق من الفهم بسؤال","desc_en":"Ends with a real question (a ? or ؟) that invites the other person to respond.","desc_ar":"ينتهي بسؤال حقيقي (؟ أو ?) يدعو الطرف الآخر إلى الرد.","tip_en":"Ask one open question before you move on.","tip_ar":"اطرح سؤالاً مفتوحاً واحداً قبل أن تنتقل.","check":{"type":"question"}}]'::jsonb, '[{"label":"LinkedIn Learning · Role play with AI coach","url":"https://training.talent.linkedin.com/introducing-role-play-with-ai-coach","as_of":"2026-10-10","benchmark_id":"SKILLS-TECH"},{"label":"Udemy · AI-powered role play for business and communication skills (custom scenarios)","url":"https://about.udemy.com/press-releases/udemy-launches-ai-powered-role-play-to-coach-professionals-on-business-and-communication-skills/","as_of":"2026-10-10","benchmark_id":"SKILLS-TECH"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10","benchmark_id":"IAEA-1917"}]'::jsonb, 'published', true, 1, 6, 'p-training-mgr', '2026-09-29T09:00:00Z')
